# situ capability map v1
# schema: header.situ
# core:   offset size align repr atomic
#
# Core axes are always shown. Any other axis appears only where it has
# been weakened below its strongest value.
#
# Offsets are byte values, or byte:bit where a field does not start on
# a byte boundary. Sizes are bytes unless suffixed with `bit`.

struct flags size=1 repr=ValueConverted atomic=NonAtomic
  flags.urgent                           offset=AbsoluteStatic(0x00) size=Fixed(1bit) align=Unaligned repr=ValueConverted atomic=NonAtomic
  flags.ack                              offset=AbsoluteStatic(0x00:1) size=Fixed(1bit) align=Unaligned repr=ValueConverted atomic=NonAtomic
  flags.priority                         offset=AbsoluteStatic(0x00:2) size=Fixed(3bit) align=Unaligned repr=ValueConverted atomic=NonAtomic
  flags.<reserved0>                      offset=AbsoluteStatic(0x00:5) size=Fixed(3bit) align=Unaligned repr=ValueConverted atomic=NonAtomic

struct header size=9 repr=ValueConverted atomic=NonAtomic
  header.version                         offset=AbsoluteStatic(0x00) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord
  header.type                            offset=AbsoluteStatic(0x01) size=Fixed(1) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord
  header.flags                           offset=AbsoluteStatic(0x02) size=Fixed(1) align=Aligned(2) repr=ValueConverted atomic=NonAtomic
  header.flags.urgent                    offset=AbsoluteStatic(0x02) size=Fixed(1bit) align=Unaligned repr=ValueConverted atomic=NonAtomic
  header.flags.ack                       offset=AbsoluteStatic(0x02:1) size=Fixed(1bit) align=Unaligned repr=ValueConverted atomic=NonAtomic
  header.flags.priority                  offset=AbsoluteStatic(0x02:2) size=Fixed(3bit) align=Unaligned repr=ValueConverted atomic=NonAtomic
  header.flags.<reserved0>               offset=AbsoluteStatic(0x02:5) size=Fixed(3bit) align=Unaligned repr=ValueConverted atomic=NonAtomic
  header.length                          offset=AbsoluteStatic(0x03) size=Fixed(2) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
  header.seq                             offset=AbsoluteStatic(0x05) size=Fixed(4) align=Aligned(1) repr=ValueConverted atomic=NonAtomic
